/**
 * esbuild wiring for the component switches that live in a source module
 * rather than in a build script.
 *
 * `module/<name>`, tool-set and OAuth components already resolve to stubs
 * generated by a build script (build-modules.mjs, build-tools.mjs,
 * build-components.mjs). Components like `syntax-highlight` are read inside a
 * module (`const ENABLED = components["syntax-highlight"] !== false`) and only
 * fold the branch that follows: esbuild's DCE removes the `if`, but the static
 * imports a module does for the component's data stay, because a disabled
 * branch does not stop the module from being included. That is how 22
 * highlight.js grammars (1.35 MiB) survived in a build that renders no color.
 *
 * Aliasing the module at resolve time removes the imports with it. The stand-in
 * has to keep the original module's export names; `COMPONENT_MODULE_STUBS`
 * records which stub serves which module, and `validateComponentStubExports`
 * fails the build when a stub and its module drift apart.
 */

import { existsSync, readFileSync } from "node:fs";
import { isAbsolute, join, resolve } from "node:path";

/**
 * Component -> the module implementing it and the stub that replaces it.
 * Paths are relative to the coding-agent package source directory.
 */
const COMPONENT_MODULES = {
	"syntax-highlight": {
		module: "src/utils/syntax-highlight.ts",
		stub: "src/utils/syntax-highlight-disabled.ts",
	},
	"jiti-modules": {
		module: "src/core/modules/jiti-loader.ts",
		stub: "src/core/modules/jiti-loader-disabled.ts",
	},
	// The Markdown renderer is imported statically by agent-session and by the
	// CLI entry, so a flavor without it swaps in a stub that throws the same
	// "not included in this build" error a runtime check would.
	"export-markdown": {
		module: "src/core/export-markdown/index.ts",
		stub: "src/core/export-markdown/index-disabled.ts",
	},
};

/**
 * The components whose install is a lazily imported package rather than a
 * static module graph. `jiti-loader` imports jiti inside a function, so
 * esbuild still resolves and bundles it; dropping the import keeps the
 * package out of the build instead of shipping bytes no code can reach.
 */
const COMPONENT_LAZY_IMPORTS = {
	"jiti-modules": "jiti",
};

/**
 * The component the standalone single file cannot carry whatever the flavor
 * says: it leaves jiti external for its zero-dependency promise, so loading
 * disk modules is off there.
 *
 * @param {{ components: Record<string, boolean | string>, singleFile?: boolean }} input
 * @returns {Record<string, boolean | string>}
 */
export function resolveComponentSwitches({ components, singleFile = false }) {
	if (!singleFile) return components;
	return { ...components, "jiti-modules": false };
}

/**
 * Removes the `import("pkg")` calls a disabled lazy component owns from the
 * compiled output. esbuild cannot dead-code-eliminate them: the import is
 * inside a function whose enclosing build is still reachable.
 *
 * @returns {import("esbuild").Plugin}
 */
export function createLazyImportDropPlugin({ components }) {
	const dropped = Object.entries(COMPONENT_LAZY_IMPORTS)
		.filter(([component]) => components[component] === false)
		.map(([, packageName]) => packageName);
	if (dropped.length === 0) return inertPlugin();
	const pattern = dropped.map((name) => name.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")).join("|");
	const filter = new RegExp(`^(${pattern})$`);
	return {
		name: "lazy-import-drops",
		setup(build) {
			build.onResolve({ filter }, (args) =>
				filter.test(args.path) ? { path: "nanopi-disabled-lazy-import", namespace: "disabled-lazy" } : undefined,
			);
			build.onLoad({ filter: /.*/, namespace: "disabled-lazy" }, () => ({
				contents: "export {};",
				loader: "js",
			}));
		},
	};
}

/**
 * The extensionless absolute path an import resolves to, or undefined for a
 * bare specifier (a package import never names a component module). Only `.js`
 * is considered: the bundle is built from compiled output.
 */
function resolveCandidate(specifier, resolveDir) {
	if (!specifier.startsWith(".") && !isAbsolute(specifier)) return undefined;
	const base = resolve(resolveDir ?? process.cwd(), specifier);
	const candidate = base.endsWith(".js") ? base.slice(0, -3) : base;
	// A component module is small and always present in the compiled tree; the
	// existence check keeps the plugin from claiming a path it only resembles.
	return existsSync(`${candidate}.js`) ? candidate : undefined;
}

/**
 * Compares the export names a stub declares with the ones its module declares.
 * Both files are parsed with a name scan rather than the TypeScript compiler:
 * every export in these two modules is a `export function name(`,
 * `export const name`, `export type name` or `export interface name` line.
 */
function exportedNames(source) {
	const names = new Set();
	for (const match of source.matchAll(/^export (?:async )?(?:function|const|type|interface|class)\s+([A-Za-z0-9_$]+)/gm)) {
		names.add(match[1]);
	}
	return names;
}

/** Throws when a stub no longer exports every name its module exports. */
export function validateComponentStubExports(codingAgentDir) {
	const details = [];
	for (const [component, { module, stub }] of Object.entries(COMPONENT_MODULES)) {
		const moduleNames = exportedNames(readFileSync(join(codingAgentDir, module), "utf8"));
		const stubNames = exportedNames(readFileSync(join(codingAgentDir, stub), "utf8"));
		const missing = [...moduleNames].filter((name) => !stubNames.has(name));
		if (missing.length > 0) {
			details.push(`component "${component}": ${stub} is missing exports of ${module}: ${missing.join(", ")}`);
		}
	}
	if (details.length > 0) {
		throw new Error(`buildconfig.json component stubs are out of sync: ${details.join("; ")}`);
	}
}

/**
 * Builds the plugin plus the list of components it replaced.
 *
 * @param {{ components: Record<string, boolean | string>, codingAgentDir: string }} options
 * @returns {{ plugin: import("esbuild").Plugin, disabledModules: string[] }}
 */
export function createComponentStubPlugin({ components, codingAgentDir }) {
	const disabled = Object.entries(COMPONENT_MODULES).filter(([component]) => components[component] === false);
	if (disabled.length === 0) return { plugin: inertPlugin(), disabledModules: [] };

	// Imports are matched by the file they resolve to, not by the specifier they
	// are written with: the module is imported as `./syntax-highlight.js` from
	// `dist/utils` and as `../../../utils/syntax-highlight.js` from
	// `dist/modes/interactive/theme`. esbuild has no "after resolving" hook, so
	// the plugin resolves the candidate itself and compares the paths.
	const modulePaths = new Map(
		disabled.map(([, { module, stub }]) => [
			join(codingAgentDir, "dist", module.replace(/^src\//, "").replace(/\.ts$/, "")),
			join(codingAgentDir, "dist", stub.replace(/^src\//, "").replace(/\.ts$/, ".js")),
		]),
	);

	return {
		plugin: {
			name: "component-module-stubs",
			setup(build) {
				build.onResolve({ filter: /.*/ }, (args) => {
					const resolved = resolveCandidate(args.path, args.resolveDir);
					if (resolved === undefined) return undefined;
					const stub = modulePaths.get(resolved);
					return stub === undefined ? undefined : { path: stub };
				});
			},
		},
		disabledModules: disabled.map(([component, { module }]) => `${component} (${module})`),
	};
}

function inertPlugin(name = "component-module-stubs") {
	return { name, setup() {} };
}

/**
 * Keeps the grammars a flavor excludes out of the artifact. `preloadLanguage`
 * writes one `import("highlight.js/lib/languages/<tag>")` per bundled tag;
 * esbuild follows every one of those specifiers even though the load is
 * deferred at runtime (the failure createComponentStubPlugin documents), and a
 * runtime guard alone folds the call site but leaves the grammar module in the
 * graph. Resolving the excluded specifiers to an empty stand-in drops the bytes
 * the same way createLazyImportDropPlugin drops `jiti`.
 *
 * The runtime half is NANOPI_BUILD_GRAMMARS: `supportsLanguage` refuses an
 * excluded tag before `preloadLanguage` is called, so the stand-in is never
 * actually loaded in normal use and an excluded code block renders plain
 * without a "Unknown language" throw from highlight.js. The stand-in is the
 * safety net for a caller that reaches `highlight()` with such a tag directly.
 *
 * `highlight.js/lib/common` is not a per-language specifier and stays: the
 * switch's default arm still needs it, and nothing in a trimmed set names it.
 *
 * @param {{ excludedGrammars: readonly string[] }} options
 * @returns {import("esbuild").Plugin}
 */
export function createGrammarDropPlugin({ excludedGrammars }) {
	const dropped = new Set(excludedGrammars);
	if (dropped.size === 0) return inertPlugin("grammar-import-drops");
	const prefix = "highlight.js/lib/languages/";
	return {
		name: "grammar-import-drops",
		setup(build) {
			build.onResolve({ filter: /^highlight\.js\/lib\/languages\// }, (args) => {
				const tag = args.path.slice(prefix.length);
				return dropped.has(tag) ? { path: `grammar:${tag}`, namespace: "dropped-grammar" } : undefined;
			});
			build.onLoad({ filter: /.*/, namespace: "dropped-grammar" }, () => ({
				// `preloadLanguage` unwraps `default` and registers only a function;
				// a non-function stand-in leaves the tag unregistered, exactly like
				// a grammar that failed to load.
				contents: "export default undefined;",
				loader: "js",
			}));
		},
	};
}
